#include "ui/scripted_dialogue.hpp"
#include "chat_store.hpp"
#include <iostream>
int main(){try{auto check=[](bool v,const char* why){if(!v)throw std::runtime_error(why);};auto amount=scriptedchat::priceInput(QStringLiteral("Предлагаю 250 000 р"));check(amount.valid&&amount.value==250000&&!amount.discount,"Typed price parsed without model");auto discount=scriptedchat::priceInput(QStringLiteral("скинь 5 000 р"));check(discount.valid&&discount.discount&&discount.value==5000,"Typed discount");check(!scriptedchat::readyToBuy(QStringLiteral("не готов забрать"))&&scriptedchat::readyToBuy(QStringLiteral("готов забрать")),"Readiness respects negation");perekup::Json car={{"name","Test car"},{"desc","2006, 1.6, механика, 197000 км"},{"full","Требуется ремонт."}};check(scriptedchat::reply(QStringLiteral("какой пробег?"),car).contains("197000"),"Existing description supplies facts");check(scriptedchat::reply(QStringLiteral("была в ДТП?"),car).contains(QStringLiteral("нет сведений")),"Script does not invent crash history");perekup::Json state={{"balance",100000},{"chat",{{"ask",50000},{"log",{"Old reply"}},{"pilotAiPending",{{"token","old"}}},{"pilotLastAiFallback",true}}},{"chatStore",{{"buy:1",{{"ask",40000},{"log",{"Saved reply"}},{"pilotLastAiCandidate","old text"}}}}}};auto logs=state["chat"]["log"];check(perekup::removeRetiredDialogueJobs(state),"Retired jobs removed");check(!state["chat"].contains("pilotAiPending")&&!state["chatStore"]["buy:1"].contains("pilotLastAiCandidate"),"Both active and archived chats migrated");check(state["chat"]["log"]==logs&&state["chat"]["ask"]==50000&&state["balance"]==100000,"History and financial state unchanged");check(!perekup::removeRetiredDialogueJobs(state),"Migration is idempotent");std::cout<<"PASS V6 scripted dialogue and migration\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
